function AddReprCommands()
    if not(bUpdatedRepr) then
        bUpdatedRepr = true
        local AiBotUtilities = import('/lua/AiBot/AI/AiBotUtilities.lua')
        _G.repru = rawget(_G, 'repru') or repr --With thanks to Balthazar for suggesting this for where e.g. FAF develop has a function that isnt yet in FAF main
        _G.reprs = rawget(_G, 'reprs') or
                function(tTable)
                    if tTable == nil then
                        return 'nil'
                    else
                        function GetVariableTypeOrValue(variable, iCurSubtableLevel)
                            if type(variable) == 'nil' then
                                return 'nil'
                            elseif type(variable) == 'number' then
                                return variable
                            elseif type(variable) == 'string' then
                                return variable
                            elseif type(variable) == 'boolean' then
                                if variable then return 'True' else return 'False' end
                            elseif type(variable) == 'function' then
                                return '<function>'
                            elseif type(variable) == 'userdata' then
                                return '<userdata>'
                            elseif type(variable) == 'thread' then
                                return '<thread>'
                            elseif type(variable) == 'table' then
                                local sCombinedTable = ''
                                for iEntry, vValue in variable do
                                    if iCurSubtableLevel and iCurSubtableLevel >= 2 then
                                        sCombinedTable = sCombinedTable..'['..iEntry..']='..'Value (stopped for performance)'
                                    else
                                        sCombinedTable = sCombinedTable..'['..iEntry..']='..GetVariableTypeOrValue(vValue, (iCurSubtableLevel or 0) + 1)
                                    end
                                end
                                return sCombinedTable
                            else
                                return '<unexpected type>'
                            end
                        end

                        return GetVariableTypeOrValue(tTable)

                    end --With thanks to Balthazar for suggesting this for where e.g. FAF develop has a function that isnt yet in FAF main
                end
        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive or AiBotUtilities.bSteamActive then
            _G.repr = function(tTable)
                if tTable == nil then
                    return 'nil'
                else
                    function GetVariableTypeOrValue(variable, iCurSubtableLevel)
                        if type(variable) == 'nil' then
                            return 'nil'
                        elseif type(variable) == 'number' then
                            return variable
                        elseif type(variable) == 'string' then
                            return variable
                        elseif type(variable) == 'boolean' then
                            if variable then return 'True' else return 'False' end
                        elseif type(variable) == 'function' then
                            return '<function>'
                        elseif type(variable) == 'userdata' then
                            return '<userdata>'
                        elseif type(variable) == 'thread' then
                            return '<thread>'
                        elseif type(variable) == 'table' then
                            local sCombinedTable = ''
                            for iEntry, vValue in variable do
                                if iCurSubtableLevel and iCurSubtableLevel >= 4 then
                                    sCombinedTable = sCombinedTable..'['..iEntry..']='..'Value (stopped for performance)'
                                else
                                    sCombinedTable = sCombinedTable..'['..iEntry..']='..GetVariableTypeOrValue(vValue, (iCurSubtableLevel or 0) + 1)
                                end
                            end
                            return sCombinedTable
                        else
                            return '<unexpected type>'
                        end
                    end

                    return GetVariableTypeOrValue(tTable, 0)
                end
            end
        end
    end
end

function DelayedArmyChangeForPings()
    WaitSeconds(0.5) --just in case some LOUD stuff hasnt loaded yet
    local SimPing = import('/lua/SimPing.lua')
    SimPing.OnArmyChange()
end

function UpdateOtherLOUDInformation()
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateOtherLOUDInformation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if not(bUpdatedOtherLOUDInfo) then
        bUpdatedOtherLOUDInfo = true
        AddReprCommands()

        local AiBotBuilding = import('/lua/AiBot/AI/AiBotBuilding.lua')
        AiBotBuilding.bShieldsCanDischarge = false

        --fix the scenarioinfo values from custom game options if are in LOUD, as it uses keys
        local LobbyOptions = import('/lua/AiBot/CustomOptions/AiBotLOUDLobbyOptions.lua')
        local vCurKey
        if bDebugMessages == true then LOG(sFunctionRef..': About to go through lobby options and update scenario info, LobbyOptions.LobbyGlobalOptions='..repru(LobbyOptions.LobbyGlobalOptions)) end
        local bUseKeyForValue
        for iEntry, tOptionData in LobbyOptions.LobbyGlobalOptions do
            vCurKey = ScenarioInfo.Options[tOptionData.key]
            bUseKeyForValue = tOptionData.bUseKeyAsValueInScenarioInfo or false
            if bDebugMessages == true then LOG(sFunctionRef..': Considering vCurKey='..(vCurKey or 'nil')..'; tOptionData.key='..(tOptionData.key or 'nil')..'; iEntry='..iEntry) end
            for iValueEntry, tValueData in tOptionData.values do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering tValueData.key='..tValueData.key or 'nil') end
                if tValueData.key == vCurKey then
                    if bDebugMessages == true then LOG(sFunctionRef..': Replacing scenario info for option Data key='..tOptionData.key..'; Scenario info value='..ScenarioInfo.Options[tOptionData.key]..'; Will change to tValueData.text='..tValueData.text..'; bUseKeyForValue='..tostring(bUseKeyForValue)..'; tValueData.key='..(tValueData.key or 'nil')) end
                    if bUseKeyForValue then
                        ScenarioInfo.Options[tOptionData.key] = tValueData.key
                    else
                        ScenarioInfo.Options[tOptionData.key] = tValueData.text
                    end
                    break
                end
            end
        end

        if not(ScenarioInfo.Options.Share) then ScenarioInfo.Options.Share = 'None' end

        if not(ScenarioInfo.MaxMapDimension) then ScenarioInfo.MaxMapDimension = math.max(ScenarioInfo.size[1],ScenarioInfo.size[2]) end
        if not(ScenarioInfo.IMAPSize) then
            if ScenarioInfo.MaxMapDimension <= 512 then
                ScenarioInfo.IntelResolution = 22.5
                ScenarioInfo.IMAPSize = 32
            elseif ScenarioInfo.MaxMapDimension == 1024 then
                ScenarioInfo.IntelResolution = 45.0
                ScenarioInfo.IMAPSize = 64
            elseif ScenarioInfo.MaxMapDimension == 2048 then
                ScenarioInfo.IntelResolution = 89.5
                ScenarioInfo.IMAPSize = 128
            else
                ScenarioInfo.IntelResolution = 180.0
                ScenarioInfo.IMAPSize = 256
            end
        end
        ForkThread(DelayedArmyChangeForPings)

        if bDebugMessages == true then LOG(sFunctionRef..': AiBotCombinedArmy='..(ScenarioInfo.Options.AiBotCombinedArmy or 'nil')) end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateUnitCategories()
    if not(bUpdatedUnitCategories) then
        bUpdatedUnitCategories = true
        --Land based:
        --lack of BOT category for experimentals
        AiBotUnitInfo.refCategoryMonkeylord = categories.CYBRAN * categories.MOBILE * categories.EXPERIMENTAL * categories.DIRECTFIRE - categories.CONSTRUCTION + categories.url0402
        AiBotUnitInfo.refCategoryMegalith = categories.CYBRAN * categories.MOBILE * categories.EXPERIMENTAL * categories.DIRECTFIRE * categories.CONSTRUCTION + categories.xrl0403
        AiBotUnitInfo.refCategoryYthotha = AiBotUnitInfo.refCategoryYthotha + categories.xsl0401
        AiBotUnitInfo.refCategoryFatboy = AiBotUnitInfo.refCategoryFatboy + categories.uel0401
        --lack of PERSONALSHIELD category:
        AiBotUnitInfo.refCategoryObsidian = AiBotUnitInfo.refCategoryObsidian + categories.ual0202
        AiBotUnitInfo.refCategoryPersonalShield = AiBotUnitInfo.refCategoryPersonalShield + categories.uel0303 + categories.ual0303
        --STEALTHFIELD
        AiBotUnitInfo.refCategoryMobileLandStealth = AiBotUnitInfo.refCategoryMobileLandStealth + categories.CYBRAN * categories.COUNTERINTELLIGENCE * categories.MOBILE * categories.LAND + categories.url0306
        AiBotUnitInfo.refCategoryStealthBoat = AiBotUnitInfo.refCategoryStealthBoat + categories.CYBRAN * categories.OVERLAYCOUNTERINTEL * categories.NAVAL * categories.DEFENSIVEBOAT + categories.xrs0205
        AiBotUnitInfo.refCategoryStealthGenerator = AiBotUnitInfo.refCategoryStealthGenerator + categories.COUNTERINTELLIGENCE * categories.STRUCTURE * categories.TECH2 + categories.ueb4203 + categories.urb4203 + categories.uab4203 + categories.xsb4203
        --STEALTH
        AiBotUnitInfo.refCategoryStealthAndCloakPersonal = AiBotUnitInfo.refCategoryStealthAndCloakPersonal + categories.xsl0101
        --BOMB
        AiBotUnitInfo.refCategoryMobileBomb = AiBotUnitInfo.refCategoryMobileBomb + categories.xrl0302
        AiBotUnitInfo.refCategoryMercy = AiBotUnitInfo.refCategoryMercy + categories.daa0206

        --Naval based:
        AiBotUnitInfo.refCategoryAntiNavy = AiBotUnitInfo.refCategoryAntiNavy + categories.DESTROYER + categories.SUBMARINE - categories.ues0201 --LOUD has submarine category
        AiBotUnitInfo.refCategorySubmarine = AiBotUnitInfo.refCategorySubmarine + categories.SUBMARINE
        AiBotUnitInfo.refCategoryGroundAA = AiBotUnitInfo.refCategoryGroundAA + categories.NAVALCARRIER
        AiBotUnitInfo.refCategoryBattlecruiser = AiBotUnitInfo.refCategoryBattlecruiser + categories.CRUISER * categories.UEF * categories.TECH3 * categories.DIRECTFIRE + categories.xes0307
        AiBotUnitInfo.refCategoryMissileShip = AiBotUnitInfo.refCategoryMissileShip + categories.NAVAL * categories.MOBILE * categories.INDIRECTFIRE * categories.BOMBARDMENT - categories.SUBMERSIBLE
        AiBotUnitInfo.refCategoryNavalAA = AiBotUnitInfo.refCategoryNavalAA + AiBotUnitInfo.refCategoryAntiAir * categories.NAVAL * categories.MOBILE + categories.CRUISER * categories.MOBILE + categories.NAVALCARRIER * categories.MOBILE - categories.xes0307 --LOUD and quiet categorise UEF battlecruiser as being a cruiser
        AiBotUnitInfo.refCategoryNavalSurface = AiBotUnitInfo.refCategoryNavalSurface + categories.DESTROYER + categories.CRUISER + categories.BATTLESHIP --destroyer is necessary, other 2 are as redundancy

        --Amphibious - in LOUD engineers and ACUs lack the amphibious category
        --Also, in QUIET destroyer doesnt have amphibious; assuming same will be the case for LOUD
        AiBotUnitInfo.refCategoryAmphibious = AiBotUnitInfo.refCategoryAmphibious + categories.ENGINEER * categories.MOBILE * categories.LAND - categories.AEON * categories.HOVER + categories.urs0201

        --Czar doesnt register the czar
        AiBotUnitInfo.refCategoryCzar = AiBotUnitInfo.refCategoryCzar + categories.uaa0310

        --Selens arent recognised as combat scouts
        AiBotUnitInfo.refCategoryCombatScout =  AiBotUnitInfo.refCategoryCombatScout + categories.xsl0101

        --Az further changes for QUIET
        local AiBotUtilities = import('/lua/AiBot/AI/AiBotUtilities.lua')
        if AiBotUtilities.bQuietModActive then
            --(QUIET removes the base exclusion of certain unit categories from lAB/addition to indirect fire, due to these being considered T0.5 units)
            AiBotUnitInfo.refCategoryIndirect = categories.LAND * categories.MOBILE * categories.INDIRECTFIRE - categories.DIRECTFIRE - AiBotUnitInfo.refCategoryLandExperimental - AiBotUnitInfo.refCategoryScathis - categories.UNSELECTABLE - categories.UNTARGETABLE
            AiBotUnitInfo.refCategoryLightAttackBot = categories.LAND * categories.DIRECTFIRE * categories.TECH1 * categories.MOBILE
            if categories.uel0106 and categories.url0106 and categories.ual0106 then
                refCategoryLightAttackBot = categories.uel0106 + categories.url0106 + categories.ual0106
            end
        end
    end
end

function LOUDBrainCreateStartVariables(aiBrain)
    --LOUD adds this info later on; however this wont solve certain issues such as score not appearing where AiBotAI+LOUD share a team - it's hoped this will be fixed in the next LOUD release (7.17)
    local X, Z = aiBrain:GetArmyStartPos()
    aiBrain.StartPosX = X
    aiBrain.StartPosZ = Z
end